        Self::with_options(api_url, session, ClientOptions::default())
    }
    pub fn with_options(
        api_url: &str,
        session: Option<Session>,
        options: ClientOptions,
    ) -> Result<Self> {
        #[cfg(target_arch = "wasm32")]
