    pub fn browser_session_status(&self) -> Option<BrowserSessionStatus> {
        let authority = self.browser_authority.as_ref()?;
        self.require_credentials().ok()?;
        Some(BrowserSessionStatus {
            principal: authority.principal.clone(),
