        CompletionRecoveryKind::Metadata => {
            canonical_uuid(job.task_id.as_deref().ok_or(Error::Protocol)?)?;
            if !matches!(job.stage.as_deref(), Some("initial" | "postprocessing"))
                || job.turn_id.is_some()
                || job.assistant_message_id.is_some()
